    R <- new array of length M
    for n in 0..M-1:
        R[n] <- p[sigma[n]] / p[n]
    return R

function first_primes(M):
    primes <- []
    c <- 2
    while |primes| < M:
        if no q in primes with q*q <= c divides c:
            append c to primes
        c <- c + 1
    return primes

