from typing import List

def first_primes(count: int) -> List[int]:
    """Return the first ``count`` primes [p_0, p_1, ...] (p_0 = 2)."""
    primes: List[int] = []
    candidate: int = 2
    while len(primes) < count:
        if all(candidate % q for q in primes if q * q <= candidate):
            primes.append(candidate)
        candidate += 1
    return primes

def displacement_ratios(primes: List[int], sigma: List[int]) -> List[float]:
    """Displacement ratios R_sigma(n) = p[sigma[n]] / p[n]."""
    return [primes[sigma[n]] / primes[n] for n in range(len(sigma))]
